/*
	VIOC_forward_bases.sqf - agregado por tools/vio_build.py (copia configurada, no es del autor de la mision).
	Parche "forward_bases": los sitios capturados funcionan como bases avanzadas (estilo Arma Reforger).
	Se compila en todas las maquinas desde init.sqf; el bucle que crea y quita las bases corre solo en el servidor.

	Parametros de lobby:
	  VIOC_FORWARD_BASES   0 = no (todo como el original), 1 = si (por defecto), 2 = si, pero solo infanteria y ligeros.
	  VIOC_FB_REQUIRE_BASE 1 = un tipo avanzado solo funciona si tu bando tiene esa fabrica viva en la base principal (por defecto), 0 = no hace falta.
	  VIOC_FB_SURCHARGE    recargo logistico en % sobre el precio normal (0 por defecto).
	  VIOC_FB_RESPAWN      1 = puedes reaparecer en las bases avanzadas seguras mas cercanas (por defecto), 0 = no.

	Que hace:
	  - Cada pueblo propio (de Oeste o Este) es una base avanzada de cuarteles (infanteria) y fabrica ligera.
	  - Sitio militar (vioc_site_mult >= 2 del parche military_sites; si no esta, por el nombre): ademas fabrica pesada.
	  - Pueblo duenio de un aerodromo (el pueblo mas cercano, a menos de VIOC_FB_AIRPORT_RANGE, de los puntos ILS y de
	    rodaje de CfgWorlds >> worldName): ademas fabrica aerea, en la plataforma.
	  - La base avanzada es un objeto ayudante invisible (Land_ClutterCutter_small_F) con cti_structure_type, asi que la
	    cola, los catalogos, las mejoras, los limites de cola, la tripulacion y el precio son los de la mision.
	    No entran en cti_structures: la IA comandante, la victoria y la basura no los ven.
	  - Menu de compra: aparece a menos de VIOC_FB_RANGE del centro del pueblo, de un campamento propio de ese pueblo o
	    de la plataforma del aerodromo. Con el Control Center a tu alcance, la lista de fabricas incluye tambien las
	    bases avanzadas a ese alcance, ordenadas de la mas cercana a la mas lejana (la primera queda elegida).
	  - Al comprar: nada de enemigos a menos de VIOC_FB_SAFE_RADIUS, tope de VIOC_FB_MAX_EMPTY vehiculos vacios por
	    jugador cerca de esa base, y lugar libre (findEmptyPosition + isFlatEmpty + sin vehiculos + sin techo; nunca
	    "CAN_COLLIDE"). Las aeronaves con piloto nacen en vuelo sobre el aerodromo, como en la base.
	  - Si se pierde el sitio (cambia cti_town_sideID) el servicio se corta en el acto en el cliente; el servidor
	    marca el ayudante (vioc_fb_off) y lo borra cuando su cola termino. Los pedidos en cola se cancelan ANTES de
	    cobrar (el cobro de la mision es despues del tiempo de construccion).
	  - IA: los refuerzos de tierra ya los acerca ai_front_spawn (no se duplica). Aqui solo se agrega el aire: una
	    aeronave comprada por un equipo IA nace sobre el aerodromo avanzado propio si queda VIOC_FB_AI_AIR_GAIN mas
	    cerca de su objetivo que la fabrica.
	Consola (LOCAL EXEC): hint (call VIOC_FB_fnc_info); VIOC_FB_INFO = [creadas, quitadas, compras_jugador, compras_IA, aire_IA, canceladas].
*/

//--- Ajustes
VIOC_FB_RANGE = 200;            // m: alcance del menu (centro del pueblo, campamento propio o plataforma)
VIOC_FB_SAFE_RADIUS = 300;      // m: sin enemigos (otros bandos, tambien la guerrilla) tan cerca
VIOC_FB_HOLD_TIME = 120;        // s tras capturar el sitio hasta que funciona como base avanzada
VIOC_FB_MAX_EMPTY = 3;          // vehiculos vacios comprados por jugador cerca de una base avanzada
VIOC_FB_EMPTY_RADIUS = 400;     // m: radio en que se cuentan esos vehiculos vacios
VIOC_FB_LIST_MAX = 8;           // bases avanzadas de un tipo como maximo en la lista del menu (las mas cercanas)
VIOC_FB_AIRPORT_RANGE = 1500;   // m: pueblo duenio de un aerodromo
VIOC_FB_AI_AIR_GAIN = 1000;     // m: la IA aerea nace en el aerodromo avanzado si queda al menos esto mas cerca de su objetivo
VIOC_FB_PERIOD = 15;            // s entre revisiones del servidor
VIOC_FB_RESPAWN_MAX = 6;        // bases avanzadas como maximo en la lista de reaparicion
VIOC_FB_REAP_MIN = 60;          // s minimos entre quitar el servicio y borrar el ayudante (deja terminar la cola)
VIOC_FB_REAP_MAX = 900;         // s maximos
if (isNil "VIOC_FB_INFO") then {VIOC_FB_INFO = [0, 0, 0, 0, 0, 0]};

VIOC_FB_fnc_mode = {
	missionNamespace getVariable ["VIOC_FORWARD_BASES", 1]
};

//--- [x, y, 0] de una posicion u objeto.
VIOC_FB_fnc_p0 = {
	private _p = if (_this isEqualType objNull) then {getPosATL _this} else {_this};
	[_p select 0, _p select 1, 0]
};

//--- [ayudante, ID del lado] -> true si la base avanzada sigue siendo de ese lado (no apagada y el pueblo es suyo).
VIOC_FB_fnc_valid = {
	params ["_h", "_sid"];
	!isNull _h
	&& {!(_h getVariable ["vioc_fb_off", false])}
	&& {(_h getVariable ["vioc_fb_side", -9]) == _sid}
	&& {((_h getVariable ["vioc_fb_town", objNull]) getVariable ["cti_town_sideID", -1]) == _sid}
};

//--- Condicion del bucle de construccion (cliente y servidor): false en cuanto el ayudante se apaga o el pueblo cambia de dueno.
VIOC_FB_fnc_waitOk = {
	params ["_f"];
	if (isNil {_f getVariable "vioc_fb_town"}) exitWith {true};
	[_f, _f getVariable ["vioc_fb_side", -9]] call VIOC_FB_fnc_valid
};

//--- [posicion, lado] -> true si no hay enemigos (los otros bandos, tambien la guerrilla) a menos de VIOC_FB_SAFE_RADIUS.
VIOC_FB_fnc_safe = {
	params ["_pos", "_side"];
	private _near = (_pos call VIOC_FB_fnc_p0) nearEntities [["Man", "Car", "Motorcycle", "Tank", "Air", "Ship", "StaticWeapon"], VIOC_FB_SAFE_RADIUS];
	private _n = 0;
	{ _n = _n + (_x countSide _near) } forEach ([west, east, resistance] - [_side]);
	_n == 0
};

//--- [lado, tipo] -> true si no se exige la fabrica en la base o el lado la tiene viva.
VIOC_FB_fnc_baseOk = {
	params ["_side", "_type"];
	if ((missionNamespace getVariable ["VIOC_FB_REQUIRE_BASE", 1]) <= 0) exitWith {true};
	[_side, _type] call CTI_CO_FNC_HasStructure
};

//--- [ayudante, unidad] -> true si la unidad esta a menos de VIOC_FB_RANGE del ayudante, del centro del pueblo o de un campamento propio.
VIOC_FB_fnc_inMenuRange = {
	params ["_h", "_unit"];
	private _p = _unit call VIOC_FB_fnc_p0;
	if ((_h distance2D _p) <= VIOC_FB_RANGE) exitWith {true};
	private _town = _h getVariable ["vioc_fb_town", objNull];
	if (isNull _town) exitWith {false};
	if ((_town distance2D _p) <= VIOC_FB_RANGE) exitWith {true};
	private _sid = _h getVariable ["vioc_fb_side", -9];
	({((_x getVariable ["cti_camp_sideID", -1]) == _sid) && {(_x distance2D _p) <= VIOC_FB_RANGE}} count (_town getVariable ["cti_town_camps", []])) > 0
};

//--- Cliente: [tipo, unidad] -> ayudantes de ese tipo del lado del jugador, validos y a su alcance (el del Control Center o
//--- el del menu de la base avanzada), del mas cercano al mas lejano, VIOC_FB_LIST_MAX como maximo.
VIOC_FB_fnc_getNear = {
	params ["_type", "_unit"];
	if ((call VIOC_FB_fnc_mode) <= 0) exitWith {[]};
	if !(_type in [CTI_BARRACKS, CTI_LIGHT, CTI_HEAVY, CTI_AIR]) exitWith {[]};
	if !([CTI_P_SideJoined, _type] call VIOC_FB_fnc_baseOk) exitWith {[]};
	private _range = missionNamespace getVariable ["CTI_BASE_PURCHASE_UNITS_RANGE_EFFECTIVE", CTI_BASE_PURCHASE_UNITS_RANGE];
	private _list = CTI_P_SideLogic getVariable ["vioc_fb_list", []];
	private _keys = [];
	{
		if ((_x getVariable ["cti_structure_type", ""]) == _type && {[_x, CTI_P_SideID] call VIOC_FB_fnc_valid}) then {
			private _d = _x distance2D _unit;
			if (_d <= _range || {_d < 2500 && {[_x, _unit] call VIOC_FB_fnc_inMenuRange}}) then {_keys pushBack [_d, _forEachIndex]};
		};
	} forEach _list;
	_keys sort true;
	if (count _keys > VIOC_FB_LIST_MAX) then {_keys resize VIOC_FB_LIST_MAX};
	_keys apply {_list select (_x select 1)}
};

//--- Cliente (update_actions.fsm, cada 2,5 s): enciende CTI_Base_<tipo>InRange si hay una base avanzada de ese tipo a tu alcance.
VIOC_FB_fnc_updateInRange = {
	if ((call VIOC_FB_fnc_mode) <= 0) exitWith {};
	private _list = CTI_P_SideLogic getVariable ["vioc_fb_list", []];
	if (count _list == 0) exitWith {};
	private _range = missionNamespace getVariable ["CTI_BASE_PURCHASE_UNITS_RANGE_EFFECTIVE", CTI_BASE_PURCHASE_UNITS_RANGE];
	private _u = vehicle player;
	private _found = [];
	{
		private _t = _x getVariable ["cti_structure_type", ""];
		if (!(_t in _found) && {[_x, CTI_P_SideID] call VIOC_FB_fnc_valid}) then {
			private _d = _x distance2D _u;
			if (_d <= _range || {_d < 2500 && {[_x, _u] call VIOC_FB_fnc_inMenuRange}}) then {_found pushBack _t};
		};
	} forEach _list;
	{
		if ([CTI_P_SideJoined, _x] call VIOC_FB_fnc_baseOk) then {
			switch (_x) do {
				case CTI_BARRACKS: {CTI_Base_BarracksInRange = true};
				case CTI_LIGHT: {CTI_Base_LightInRange = true};
				case CTI_HEAVY: {CTI_Base_HeavyInRange = true};
				case CTI_AIR: {CTI_Base_AirInRange = true};
			};
		};
	} forEach _found;
};

//--- Lugares libres (comunes: los usan el cliente que compra y el servidor para la IA). Nunca "CAN_COLLIDE".
//--- [p] -> true si no hay techo encima.
VIOC_FB_fnc_roofFree = {
	params ["_p"];
	(lineIntersectsSurfaces [(AGLToASL _p) vectorAdd [0, 0, 0.5], (AGLToASL _p) vectorAdd [0, 0, 40], objNull, objNull, false, 1, "GEOM", "NONE"]) isEqualTo []
};

//--- [p, [ils, eje, largo], ancho] -> true si p esta en la franja de la pista (eje desde el punto ILS hacia los puntos de rodaje).
VIOC_FB_fnc_onRunway = {
	params ["_p", "_rwy", "_lat"];
	if (count _rwy < 3) exitWith {false};
	_rwy params ["_ils", "_ax", "_len"];
	private _dx = (_p select 0) - (_ils select 0);
	private _dy = (_p select 1) - (_ils select 1);
	private _t = (_dx * (_ax select 0)) + (_dy * (_ax select 1));
	private _l = abs ((_dx * (_ax select 1)) - (_dy * (_ax select 0)));
	(_t > -300) && {_t < (_len + 300)} && {_l < _lat}
};

//--- [clase] -> radio en m para buscar lugar. sizeOf da 0 si ese modelo aun no se cargo: entonces mapSize del config y un
//--- minimo por tipo (helicoptero 15, avion 20, vehiculo 6).
VIOC_FB_fnc_radius = {
	params ["_class"];
	private _kind = switch (true) do {case (_class isKindOf "Plane"): {0}; case (_class isKindOf "Helicopter"): {1}; case (_class isKindOf "Man"): {3}; default {2}};
	private _s = sizeOf _class;
	if (_s > 0) exitWith {(_s / 2) max ([8, 6, 3, 0.5] select _kind)};
	((getNumber (configFile >> "CfgVehicles" >> _class >> "mapSize")) / 2) max ([20, 15, 6, 0.5] select _kind)
};

//--- [p, a, b] -> distancia 2D de p al segmento a-b.
VIOC_FB_fnc_distSeg = {
	params ["_p", "_a", "_b"];
	private _abx = (_b select 0) - (_a select 0);
	private _aby = (_b select 1) - (_a select 1);
	private _l2 = (_abx * _abx) + (_aby * _aby);
	private _t = if (_l2 < 0.01) then {0} else {((((_p select 0) - (_a select 0)) * _abx) + (((_p select 1) - (_a select 1)) * _aby)) / _l2};
	_t = (_t max 0) min 1;
	_p distance2D [(_a select 0) + (_abx * _t), (_a select 1) + (_aby * _t), 0]
};

//--- [anclas, clase, es hombre] -> [lugar, direccion] o [] (infanteria y vehiculos de tierra).
VIOC_FB_fnc_spotLand = {
	params ["_anchors", "_class", "_isMan"];
	private _rad = if (_isMan) then {0.5} else {[_class] call VIOC_FB_fnc_radius};
	private _res = [];
	{
		private _a = _x call VIOC_FB_fnc_p0;
		for "_i" from 1 to 6 do {
			private _c = if (_i == 1) then {_a} else {_a getPos [8 + random 50, random 360]};
			private _p = _c findEmptyPosition [0, [45, 25] select _isMan, _class];
			if (count _p > 1) then {
				_p = [_p select 0, _p select 1, 0];
				if (!(surfaceIsWater _p)
					&& {(_p distance2D _a) < 110}
					&& {_isMan || {_i > 4} || {!(isOnRoad _p)}}
					&& {_isMan || {count (_p isFlatEmpty [-1, -1, 0.35, _rad, 0, false, objNull]) > 0}}
					&& {(_p nearEntities [["AllVehicles"], _rad + 2]) isEqualTo []}
					&& {[_p] call VIOC_FB_fnc_roofFree}) then {
					_res = [_p, _a getDir _p];
				};
			};
			if (count _res > 0) exitWith {};
		};
		if (count _res > 0) exitWith {};
	} forEach _anchors;
	_res
};

//--- [ancla, clase, pista, radio min, radio max] -> [lugar, direccion] o [] (helicoptero: claro plano, sin arboles ni edificios,
//--- sin vehiculos, fuera de la pista). Nunca devuelve el ancla misma.
VIOC_FB_fnc_spotHeli = {
	params ["_anchor", "_class", "_rwy", ["_rmin", 20], ["_rmax", 130]];
	private _a = _anchor call VIOC_FB_fnc_p0;
	private _r = [_class] call VIOC_FB_fnc_radius;
	private _res = [];
	for "_i" from 1 to 12 do {
		private _c = _a getPos [_rmin + random (_rmax - _rmin), random 360];
		private _p = _c findEmptyPosition [0, 40, _class];
		if (count _p > 1) then {
			_p = [_p select 0, _p select 1, 0];
			if (!(surfaceIsWater _p)
				&& {(_p distance2D _a) < (_rmax + 70)}
				&& {!([_p, _rwy, 70] call VIOC_FB_fnc_onRunway)}
				&& {count (_p isFlatEmpty [-1, -1, 0.25, _r, 0, false, objNull]) > 0}
				&& {(nearestTerrainObjects [_p, ["TREE", "SMALL TREE", "BUSH", "BUILDING", "HOUSE", "ROCK", "ROCKS", "WALL", "FENCE", "POWER LINES", "TRANSMITTER", "RUIN", "BUNKER", "FORTRESS", "VIEW-TOWER", "WATERTOWER", "LIGHTHOUSE", "CHURCH", "CHAPEL", "CROSS", "FUELSTATION", "HOSPITAL", "STACK", "QUAY"], _r + 4, false, true]) isEqualTo []}
				&& {(_p nearEntities [["AllVehicles"], _r + 6]) isEqualTo []}
				&& {[_p] call VIOC_FB_fnc_roofFree}) then {
				_res = [_p, _a getDir _p];
			};
		};
		if (count _res > 0) exitWith {};
	};
	_res
};

//--- Aviones vacios: lugares de estacionamiento junto al rodaje (no en el), fuera de la pista. Se generan desplazando cada punto de
//--- rodaje en perpendicular a la pista, hacia el lado contrario a ella (r+10, r+25, r+40 m), empezando por el final de la plataforma.
//--- Se descartan: la franja de la pista (35 m + r del eje), cerca de un tramo de rodaje (r + 8 m), y a menos de max(40, r + 25) m
//--- del ultimo punto de salida de pista (donde paran los aviones de landAt) y de los 2 primeros de entrada (inicio del rodaje de despegue).
//--- Los puntos que estan sobre la pista (salidas de pista) se desplazan hacia el lado del rodaje y la plataforma. Los candidatos
//--- se ordenan por distancia a la plataforma (_ref), para preferir estacionar alli.
//--- [rodaje de salida, rodaje de entrada, pista, radio, plataforma] -> [[lugar, direccion], ...] (solo geometria).
VIOC_FB_fnc_planeCands = {
	params ["_off", "_in", "_rwy", "_r", ["_ref", []]];
	if (count _rwy < 3 || {(count _off) + (count _in) == 0}) exitWith {[]};
	_rwy params ["_ils", "_ax", "_len"];
	private _perp = [-(_ax select 1), _ax select 0];
	private _segs = [];
	{
		private _l = _x;
		for "_i" from 0 to ((count _l) - 2) do {_segs pushBack [_l select _i, _l select (_i + 1)]};
	} forEach [_off, _in];
	private _keep = [];
	if (count _off > 0) then {_keep pushBack (_off select ((count _off) - 1))};
	{ if (_forEachIndex < 2) then {_keep pushBack _x} } forEach _in;
	private _clear = (_r + 25) max 40;
	private _pts = (+_off);
	reverse _pts;
	_pts append _in;
	private _fnc_lat = {(((_this select 0) - (_ils select 0)) * (_perp select 0)) + (((_this select 1) - (_ils select 1)) * (_perp select 1))};
	private _side0 = 0;
	{ private _l = _x call _fnc_lat; if ((abs _l) >= 15) then {_side0 = _side0 + _l} } forEach _pts;
	_side0 = [1, -1] select (_side0 < 0);
	private _res = [];
	{
		private _q = _x;
		private _lat = _q call _fnc_lat;
		private _sg = if ((abs _lat) < 15) then {_side0} else {[1, -1] select (_lat < 0)};
		{
			private _c = [(_q select 0) + ((_perp select 0) * _sg * _x), (_q select 1) + ((_perp select 1) * _sg * _x), 0];
			if (!([_c, _rwy, 35 + _r] call VIOC_FB_fnc_onRunway)
				&& {(_segs findIf {([_c, _x select 0, _x select 1] call VIOC_FB_fnc_distSeg) < (_r + 8)}) < 0}
				&& {(_keep findIf {(_x distance2D _c) < _clear}) < 0}
				&& {(_res findIf {((_x select 0) distance2D _c) < ((2 * _r) + 4)}) < 0}) then {
				_res pushBack [_c, _c getDir _q]; //--- mirando hacia el rodaje
			};
		} forEach [_r + 10, _r + 25, _r + 40];
	} forEach _pts;
	if (count _ref > 1) then {
		private _keys = _res apply {[(_x select 0) distance2D _ref, _x]};
		_keys sort true;
		_res = _keys apply {_x select 1};
	};
	_res
};

//--- [lugar, radio, mirar vehiculos] -> true si el lugar sirve: tierra, plano, sin objetos del mapa, sin vehiculos, sin techo.
VIOC_FB_fnc_planeFree = {
	params ["_c", "_r", ["_veh", true]];
	!(surfaceIsWater _c)
	&& {count (_c isFlatEmpty [-1, -1, 0.2, _r, 0, false, objNull]) > 0}
	&& {(nearestTerrainObjects [_c, ["TREE", "SMALL TREE", "BUSH", "BUILDING", "HOUSE", "ROCK", "ROCKS", "WALL", "FENCE", "POWER LINES", "TRANSMITTER", "RUIN", "BUNKER", "FORTRESS", "VIEW-TOWER", "WATERTOWER", "LIGHTHOUSE", "CHURCH", "CHAPEL", "CROSS", "FUELSTATION", "HOSPITAL", "STACK", "QUAY"], _r + 2, false, true]) isEqualTo []}
	&& {!_veh || {(_c nearEntities [["AllVehicles"], _r + 4]) isEqualTo []}}
	&& {[_c] call VIOC_FB_fnc_roofFree}
};

//--- [rodaje de salida, rodaje de entrada, clase, pista] -> [lugar, direccion] o [].
VIOC_FB_fnc_spotPlane = {
	params ["_off", "_in", "_class", "_rwy", ["_ref", []]];
	private _r = [_class] call VIOC_FB_fnc_radius;
	private _res = [];
	{
		if ([_x select 0, _r] call VIOC_FB_fnc_planeFree) exitWith {_res = +_x};
	} forEach ([_off, _in, _rwy, _r, _ref] call VIOC_FB_fnc_planeCands);
	_res
};

//--- [ayudante, clase] -> [lugar, direccion] o [] segun el tipo de unidad.
VIOC_FB_fnc_spot = {
	params ["_h", "_class"];
	private _town = _h getVariable ["vioc_fb_town", objNull];
	private _sid = _h getVariable ["vioc_fb_side", -9];
	private _anchors = [_h];
	if (!isNull _town) then {
		_anchors pushBack _town;
		{ if ((_x getVariable ["cti_camp_sideID", -1]) == _sid) then {_anchors pushBack _x} } forEach (_town getVariable ["cti_town_camps", []]);
	};
	switch (true) do {
		case (_class isKindOf "Man"): {[_anchors, _class, true] call VIOC_FB_fnc_spotLand};
		case (_class isKindOf "Helicopter"): {
			private _sh = [_h, _class, _h getVariable ["vioc_fb_rwy", []]] call VIOC_FB_fnc_spotHeli;
			if (count _sh < 2) then {_sh = [_h, _class, _h getVariable ["vioc_fb_rwy", []], 130, 280] call VIOC_FB_fnc_spotHeli};
			_sh
		};
		case (_class isKindOf "Plane"): {[_h getVariable ["vioc_fb_taxi", []], _h getVariable ["vioc_fb_taxiIn", []], _class, _h getVariable ["vioc_fb_rwy", []], _h call VIOC_FB_fnc_p0] call VIOC_FB_fnc_spotPlane};
		case (_class isKindOf "Ship"): {[]};
		default {[_anchors, _class, false] call VIOC_FB_fnc_spotLand}; //--- vehiculos de tierra y cargas (pods, cajas)
	}
};

//--- Cliente: vehiculos vacios vivos que el jugador compro en bases avanzadas cerca de este ayudante.
VIOC_FB_fnc_emptyCount = {
	params ["_h"];
	private _uid = getPlayerUID player;
	{alive _x && {(_x getVariable ["vioc_fb_owner", ""]) == _uid} && {({alive _x} count (crew _x)) == 0}} count ((_h call VIOC_FB_fnc_p0) nearEntities [["Car", "Motorcycle", "Tank", "Air", "Ship"], VIOC_FB_EMPTY_RADIUS])
};

//--- Cliente: [ayudante, clase, vacio] -> "" o el motivo por el que no se puede comprar ahi.
VIOC_FB_fnc_blockReason = {
	params ["_h", "_model", "_empty"];
	private _tn = (_h getVariable ["vioc_fb_town", objNull]) getVariable ["cti_town_name", "?"];
	if !([_h, CTI_P_SideID] call VIOC_FB_fnc_valid) exitWith {format ["%1 ya no es una base avanzada de tu bando.", _tn]};
	if !([CTI_P_SideJoined, _h getVariable ["cti_structure_type", ""]] call VIOC_FB_fnc_baseOk) exitWith {"Para comprar este tipo en una base avanzada tu bando necesita esa fabrica viva en la base principal."};
	if !([_h, CTI_P_SideJoined] call VIOC_FB_fnc_safe) exitWith {format ["Hay enemigos a menos de %1 m de la base avanzada de %2.", VIOC_FB_SAFE_RADIUS, _tn]};
	if (_empty && {_model isKindOf "Plane"} && {!(_h getVariable ["vioc_fb_planeok", false])}) exitWith {format ["El aerodromo de %1 no tiene lugar para estacionar aviones vacios (pista corta o sin plataforma): compralo con piloto (sale en vuelo) o usa otro aerodromo.", _tn]};
	if (_empty && {([_h] call VIOC_FB_fnc_emptyCount) >= VIOC_FB_MAX_EMPTY}) exitWith {format ["Ya tienes %1 vehiculos vacios cerca de la base avanzada de %2 (maximo %1). Usa o pierde alguno antes.", VIOC_FB_MAX_EMPTY, _tn]};
	""
};

//--- Cliente, menu de compra (Events_UI_PurchaseMenu.sqf, onPurchase): [fabrica, clase] -> false (con aviso) si no se puede.
VIOC_FB_fnc_purchaseCheck = {
