//--- Cliente, al terminar la construccion y ANTES de cobrar (Client_OnPurchaseOrderReceived.sqf):
//--- [fabrica, modelo, info del vehiculo] -> [] (no es base avanzada), ["CANCEL"] o ["OK", lugar, direccion, multiplicador de precio].
VIOC_FB_fnc_orderGate = {
	params ["_h", "_model", "_vi"];
