			_res = ["OK", _h call VIOC_FB_fnc_p0, _dir, _mult]; //--- con piloto: nace en vuelo sobre el aerodromo, como en la base
		} else {
			private _spot = [_h, _model] call VIOC_FB_fnc_spot;
			if (count _spot > 1) then {_res = ["OK", _spot select 0, _spot select 1, _mult]} else {_msg = format ["No hay un lugar libre para esa unidad en la base avanzada de %1.", _tn]};
		};
	};
	if (_msg != "") exitWith {
		VIOC_FB_INFO set [5, (VIOC_FB_INFO select 5) + 1];
		hint parseText format ["<t size='1.3' color='#2394ef'>Base avanzada</t><br /><br />%1<br />Pedido cancelado: no se cobro nada.", _msg];
		["CANCEL"]
	};
	VIOC_FB_INFO set [2, (VIOC_FB_INFO select 2) + 1];
	_res
};

//--- Servidor, compra para un equipo IA en una base avanzada (Server_HandleAIPurchase.sqf), ANTES de cobrar:
