//--- Servidor: aeronave comprada para un equipo IA -> [lugar, direccion] sobre el aerodromo avanzado propio que quede al menos
//--- VIOC_FB_AI_AIR_GAIN mas cerca del objetivo del equipo (cti_order_pos, o su lider) que la fabrica; [] = sale de la fabrica.
//--- ai_front_spawn no toca el aire, asi que no se pisan.
VIOC_FB_fnc_aiAirPos = {
	params ["_model", "_group", "_side", "_factory"];
	if ((call VIOC_FB_fnc_mode) != 1) exitWith {[]};
	if (!(_group isEqualType grpNull) || {isNull _group} || {isNull leader _group} || {isPlayer leader _group}) exitWith {[]};
	if !(_model isKindOf "Air") exitWith {[]};
	private _tgt = _group getVariable ["cti_order_pos", objNull];
	if (_tgt isEqualType objNull) then {_tgt = if (isNull _tgt) then {getPosATL (leader _group)} else {getPosATL _tgt}};
	if (!(_tgt isEqualType []) || {count _tgt < 2}) exitWith {[]};
	_tgt = [_tgt select 0, _tgt select 1, 0];
	if ((_tgt distance2D [0, 0, 0]) < 100) then {_tgt = (leader _group) call VIOC_FB_fnc_p0}; //--- equipo nuevo sin objetivo (cti_order_pos [0,0])
	private _sid = (_side) call CTI_CO_FNC_GetSideID;
	private _bd = (_factory distance2D _tgt) - VIOC_FB_AI_AIR_GAIN;
	private _best = objNull;
	{
		if ((_x getVariable ["cti_structure_type", ""]) == CTI_AIR && {(_x distance2D _tgt) < _bd} && {[_x, _sid] call VIOC_FB_fnc_valid} && {[_x, _side] call VIOC_FB_fnc_safe}) then {_best = _x; _bd = _x distance2D _tgt};
	} forEach (((_side) call CTI_CO_FNC_GetSideLogic) getVariable ["vioc_fb_list", []]);
	if (isNull _best) exitWith {[]};
	VIOC_FB_INFO set [4, (VIOC_FB_INFO select 4) + 1];
	[_best call VIOC_FB_fnc_p0, _best getDir _tgt]
};

//--- Cliente, menu de reaparicion: cuarteles avanzados propios y seguros, los VIOC_FB_RESPAWN_MAX mas cercanos a donde moriste.
//--- La lista se pide cada 0,1 s mientras el menu esta abierto (GUI_RespawnMenu.sqf): se recalcula como mucho cada 2 s.
VIOC_FB_fnc_respawnList = {
	if ((call VIOC_FB_fnc_mode) <= 0 || {(missionNamespace getVariable ["VIOC_FB_RESPAWN", 1]) <= 0}) exitWith {[]};
	if (!isNil "VIOC_FB_RSP_CACHE" && {(time - (VIOC_FB_RSP_CACHE select 0)) < 2}) exitWith {+(VIOC_FB_RSP_CACHE select 1)};
	private _c = missionNamespace getVariable ["CTI_DeathPosition", getPosATL player];
	private _list = CTI_P_SideLogic getVariable ["vioc_fb_list", []];
	private _keys = [];
	{
		if ((_x getVariable ["cti_structure_type", ""]) == CTI_BARRACKS && {[_x, CTI_P_SideID] call VIOC_FB_fnc_valid}) then {_keys pushBack [_x distance2D _c, _forEachIndex]};
	} forEach _list;
	_keys sort true;
	private _res = [];
	{
		private _h = _list select (_x select 1);
		if ([_h, CTI_P_SideJoined] call VIOC_FB_fnc_safe) then {_res pushBack _h};
		if (count _res >= VIOC_FB_RESPAWN_MAX) exitWith {};
	} forEach _keys;
	VIOC_FB_RSP_CACHE = [time, +_res];
	_res
};

//--- Consola: texto con las bases avanzadas de los dos bandos.
VIOC_FB_fnc_info = {
	private _nl = toString [10];
	private _txt = format ["Bases avanzadas (modo %1, recargo %2, exigir fabrica %3). INFO %4", call VIOC_FB_fnc_mode, missionNamespace getVariable ["VIOC_FB_SURCHARGE", 0], missionNamespace getVariable ["VIOC_FB_REQUIRE_BASE", 1], VIOC_FB_INFO];
	{
		private _side = _x;
