		private _by = createHashMap;
		{
			private _tn = (_x getVariable ["vioc_fb_town", objNull]) getVariable ["cti_town_name", "?"];
			private _ok = [_x, _x getVariable ["vioc_fb_side", -9]] call VIOC_FB_fnc_valid;
			private _cur = _by getOrDefault [_tn, []];
