//--- ===================================== SERVIDOR =====================================

//--- [punto, pista, puntos del aerodromo] -> el punto, o si esta en la franja de la pista, el mismo punto llevado a 70 m del eje hacia el
//--- lado del rodaje (o el otro lado si alli hay agua). Asi la "plataforma" nunca queda sobre la pista.
VIOC_FB_fnc_besideRunway = {
	params ["_p", "_rwy", "_pts"];
	if !([_p, _rwy, 40] call VIOC_FB_fnc_onRunway) exitWith {_p};
	_rwy params ["_ils", "_ax"];
	private _perp = [-(_ax select 1), _ax select 0];
	private _fl = {(((_this select 0) - (_ils select 0)) * (_perp select 0)) + (((_this select 1) - (_ils select 1)) * (_perp select 1))};
	private _sum = 0;
	{ _sum = _sum + (_x call _fl) } forEach _pts;
	private _sg = [1, -1] select (_sum < 0);
	private _res = _p;
	{
		private _d = (_sg * _x * 70) - (_p call _fl);
		private _q = [(_p select 0) + ((_perp select 0) * _d), (_p select 1) + ((_perp select 1) * _d), 0];
		if !(surfaceIsWater _q) exitWith {_res = _q};
	} forEach [1, -1];
	_res
};

//--- Aeropuertos de CfgWorlds: [indice, [ils, eje, largo], rodaje de salida, todos los puntos].
VIOC_FB_fnc_airports = {
	private _wcfg = configFile >> "CfgWorlds" >> worldName;
	private _cfgs = [_wcfg];
	if (isClass (_wcfg >> "SecondaryAirports")) then {_cfgs append ("true" configClasses (_wcfg >> "SecondaryAirports"))};
	private _fnc_in = {(_this select 0) > 0 && {(_this select 1) > 0} && {(_this select 0) < worldSize} && {(_this select 1) < worldSize}};
	private _res = [];
	{
		private _c = _x;
		private _ils = getArray (_c >> "ilsPosition");
		if (count _ils > 1 && {(_ils select 0) isEqualType 0} && {(_ils select 1) isEqualType 0} && {_ils call _fnc_in}) then {
			_ils = [_ils select 0, _ils select 1, 0];
			private _off = [];
			private _in = [];
			private _pts = [_ils];
			{
				private _flat = getArray (_c >> _x);
				private _dst = [_in, _off] select (_x == "ilsTaxiOff");
				for "_i" from 0 to ((count _flat) - 2) step 2 do {
					private _q = [_flat select _i, _flat select (_i + 1), 0];
					if ((_q select 0) isEqualType 0 && {(_q select 1) isEqualType 0} && {_q call _fnc_in}) then {
						_pts pushBack _q;
						_dst pushBack _q;
					};
				};
			} forEach ["ilsTaxiIn", "ilsTaxiOff"];
			//--- Eje de la pista: ilsDirection en el plano, del lado donde estan los puntos de rodaje.
			private _dir = getArray (_c >> "ilsDirection");
			private _ax = if (count _dir > 2 && {(_dir select 0) isEqualType 0} && {(_dir select 2) isEqualType 0}) then {[_dir select 0, _dir select 2]} else {[0, 1]};
			private _n = sqrt (((_ax select 0) ^ 2) + ((_ax select 1) ^ 2));
			_ax = if (_n > 0.001) then {[(_ax select 0) / _n, (_ax select 1) / _n]} else {[0, 1]};
			private _sum = 0;
			private _ts = [];
			{
				private _t = (((_x select 0) - (_ils select 0)) * (_ax select 0)) + (((_x select 1) - (_ils select 1)) * (_ax select 1));
				_sum = _sum + _t; _ts pushBack _t;
			} forEach (_pts - [_ils]);
			if (_sum < 0) then {_ax = [-(_ax select 0), -(_ax select 1)]; _ts = _ts apply {-_x}};
			private _len = 300;
			{ _len = _len max _x } forEach _ts;
			_len = _len min 4000;
			//--- [indice, pista, rodaje de salida, puntos, plataforma, pueblo, rodaje de entrada, hay estacionamiento para aviones]
			private _rwy = [_ils, _ax, _len];
			private _planeOk = (([_off, _in, _rwy, 12] call VIOC_FB_fnc_planeCands) findIf {[_x select 0, 12, false] call VIOC_FB_fnc_planeFree}) >= 0;
			_res pushBack [_forEachIndex, _rwy, _off, _pts, _ils, objNull, _in, _planeOk];
		};
	} forEach _cfgs;
	_res
};

//--- Clase de cada pueblo: ["town" | "military" | "airfield", indice del aeropuerto en VIOC_FB_AIRPORTS o -1].
VIOC_FB_fnc_classify = {
	VIOC_FB_AIRPORTS = call VIOC_FB_fnc_airports;
	{ _x setVariable ["vioc_fb_class", ["town", -1]] } forEach CTI_Towns;
	{
		private _ap = _x;
		private _apIdx = _forEachIndex;
		private _best = objNull;
		private _bd = VIOC_FB_AIRPORT_RANGE;
		{
			private _town = _x;
			{ private _d = _town distance2D _x; if (_d < _bd) then {_bd = _d; _best = _town} } forEach (_ap select 3);
		} forEach CTI_Towns;
		if (!isNull _best) then {
			//--- Plataforma = el punto del aeropuerto mas cercano al pueblo, fuera de la franja de la pista si hay alguno.
			private _cands = (_ap select 3) select {!([_x, _ap select 1, 40] call VIOC_FB_fnc_onRunway)};
			if (count _cands == 0) then {_cands = _ap select 3};
			private _apron = _cands select 0;
			{ if ((_best distance2D _x) < (_best distance2D _apron)) then {_apron = _x} } forEach _cands;
			_apron = [_apron, _ap select 1, _ap select 3] call VIOC_FB_fnc_besideRunway;
			_ap set [4, _apron];
			_ap set [5, _best];
			_best setVariable ["vioc_fb_class", ["airfield", _apIdx]];
		};
	} forEach VIOC_FB_AIRPORTS;
	{
		if (((_x getVariable ["vioc_fb_class", ["town", -1]]) select 0) == "town") then {
			private _mult = _x getVariable ["vioc_site_mult", -1];
			private _mil = if (_mult >= 0) then {_mult >= 2} else {
				private _w = (toLower (_x getVariable ["cti_town_name", ""])) splitString " -_.,;:()[]/'";
				count (_w arrayIntersect ["military", "base", "barracks", "garrison", "airbase", "airport", "airfield", "aerodrome", "airstrip", "aeroport"]) > 0
			};
			if (_mil) then {_x setVariable ["vioc_fb_class", ["military", -1]]};
		};
	} forEach CTI_Towns;
	diag_log format ["[VIOC forward_bases] %1 aeropuertos en %2; aerodromos [pueblo, estacionamiento de aviones]: %3; militares: %4", count VIOC_FB_AIRPORTS, worldName,
		(VIOC_FB_AIRPORTS select {!isNull (_x select 5)}) apply {[(_x select 5) getVariable ["cti_town_name", "?"], _x select 7]},
		(CTI_Towns select {((_x getVariable ["vioc_fb_class", ["town", -1]]) select 0) == "military"}) apply {_x getVariable ["cti_town_name", "?"]}];
};

//--- [pueblo, lado] -> crea los ayudantes de ese lado en el pueblo.
VIOC_FB_fnc_build = {
	params ["_town", "_side"];
	private _sid = (_side) call CTI_CO_FNC_GetSideID;
	private _logic = (_side) call CTI_CO_FNC_GetSideLogic;
	if (isNull _logic) exitWith {};
	private _cls = _town getVariable ["vioc_fb_class", ["town", -1]];
	private _kind = _cls select 0;
	private _types = [CTI_BARRACKS, CTI_LIGHT];
	if ((call VIOC_FB_fnc_mode) == 1) then {
		if (_kind in ["military", "airfield"]) then {_types pushBack CTI_HEAVY};
		if (_kind == "airfield" && {(_cls select 1) >= 0}) then {_types pushBack CTI_AIR};
	};
	private _tp = _town call VIOC_FB_fnc_p0;
	private _mine = [];
	{
		private _type = _x;
		private _pos = _tp;
		private _ap = [];
		if (_type == CTI_AIR) then {_ap = VIOC_FB_AIRPORTS select (_cls select 1); _pos = +(_ap select 4)};
		private _h = "Land_ClutterCutter_small_F" createVehicle _pos;
		_h setPosATL _pos;
		_h setVariable ["VIOC_KEEP", true];
		_h setVariable ["cti_structure_type", _type, true];
		_h setVariable ["vioc_fb_town", _town, true];
		_h setVariable ["vioc_fb_side", _sid, true];
		_h setVariable ["vioc_fb_kind", _kind, true];
		if (_type == CTI_AIR) then {
			_h setVariable ["vioc_fb_taxi", +(_ap select 2), true];
			_h setVariable ["vioc_fb_taxiIn", +(_ap select 6), true];
			_h setVariable ["vioc_fb_rwy", +(_ap select 1), true];
			_h setVariable ["vioc_fb_planeok", _ap select 7, true];
		};
		_mine pushBack _h;
	} forEach _types;
	_town setVariable ["vioc_fb_helpers", _mine];
	private _list = (_logic getVariable ["vioc_fb_list", []]) select {!isNull _x};
	_list append _mine;
	_logic setVariable ["vioc_fb_list", _list, true];
	VIOC_FB_INFO set [0, (VIOC_FB_INFO select 0) + (count _mine)];
	diag_log format ["[VIOC forward_bases] %1: base avanzada de %2 (%3) %4", _town getVariable ["cti_town_name", "?"], _side, _kind, _types];
};

//--- [pueblo] -> apaga sus ayudantes (el servicio se corta ya) y los deja para borrar cuando termine su cola.
VIOC_FB_fnc_clear = {
	params ["_town"];
	private _old = _town getVariable ["vioc_fb_helpers", []];
	if (count _old == 0) exitWith {};
	_town setVariable ["vioc_fb_helpers", []];
	{
		if (!isNull _x) then {
			_x setVariable ["vioc_fb_off", true, true];
			VIOC_FB_OFF pushBack [_x, time];
			private _logic = ((_x getVariable ["vioc_fb_side", -9]) call CTI_CO_FNC_GetSideFromID) call CTI_CO_FNC_GetSideLogic;
			if (!isNull _logic) then {_logic setVariable ["vioc_fb_list", (_logic getVariable ["vioc_fb_list", []]) - [_x, objNull], true]};
		};
	} forEach _old;
	VIOC_FB_INFO set [1, (VIOC_FB_INFO select 1) + (count _old)];
};

//--- [ayudante apagado] -> cancela los pedidos que esperan en su cola (no el que se esta procesando): cada comprador jugador recibe
//--- Client_OnPurchaseOrderCancelled (lo quita de su lista y libera CTI_QUEUE_<tipo> y su cola de unidades).
VIOC_FB_fnc_flushQueue = {
	params ["_h"];
	private _list = _h getVariable ["cti_queue_processing", []];
	if (count _list < 2) exitWith {};
	{
		_x params ["_seed", "_cls", "_rt", "_buyer", "_team", "_toai", "_vi", "_side", ["_uc", 1]];
		if (!isNull _buyer && {isPlayer leader _buyer}) then {[["CLIENT", leader _buyer], "Client_OnPurchaseOrderCancelled", [_seed, _cls, _h, _uc]] call CTI_CO_FNC_NetSend};
		if (_team isEqualType grpNull && {!isNull _team} && {_team != _buyer} && {isPlayer leader _team}) then {[["CLIENT", leader _team], "Client_OnPurchaseOrderCancelled", [_seed, _cls, _h, _uc]] call CTI_CO_FNC_NetSend};
	} forEach (_list select [1, (count _list) - 1]);
	_h setVariable ["cti_queue_processing", [_list select 0]];
	_h setVariable ["cti_queue_processing_count", 1];
	diag_log format ["[VIOC forward_bases] cola atascada en %1: %2 pedidos cancelados sin cobro", (_h getVariable ["vioc_fb_town", objNull]) getVariable ["cti_town_name", "?"], (count _list) - 1];
};

VIOC_FB_fnc_tick = {
	{
		private _town = _x;
		private _sid = _town getVariable ["cti_town_sideID", -1];
		private _last = _town getVariable ["vioc_fb_lastsid", -2];
		if (_sid != _last) then {
			_town setVariable ["vioc_fb_lastsid", _sid];
			_town setVariable ["vioc_fb_since", [time, -1e6] select (_last == -2)];
			[_town] call VIOC_FB_fnc_clear;
		};
		if ((_sid == CTI_WEST_ID || {_sid == CTI_EAST_ID}) && {count (_town getVariable ["vioc_fb_helpers", []]) == 0} && {(time - (_town getVariable ["vioc_fb_since", -1e6])) >= VIOC_FB_HOLD_TIME}) then {
			[_town, (_sid) call CTI_CO_FNC_GetSideFromID] call VIOC_FB_fnc_build;
		};
	} forEach CTI_Towns;
	//--- Borrar los ayudantes apagados cuyo hilo de cola ya termino. Nunca se borra uno con cola (Client_PurchaseQueueRelease
	//--- lee cti_structure_type del objeto): si a los VIOC_FB_REAP_MAX s todavia la tiene, se cancelan los pedidos que esperan
	//--- (el comprador libera su cola, como en Server_OnClientPurchaseCancelled; nada se cobra) y se sigue esperando.
	{
		_x params ["_h", "_t"];
		if (isNull _h) then {VIOC_FB_OFF set [_forEachIndex, -1]} else {
			if (isNil {_h getVariable "cti_queue_processing"}) then {
				if ((time - _t) > VIOC_FB_REAP_MIN) then {deleteVehicle _h; VIOC_FB_OFF set [_forEachIndex, -1]};
			} else {
				if ((time - _t) > VIOC_FB_REAP_MAX) then {[_h] call VIOC_FB_fnc_flushQueue; _x set [1, time - VIOC_FB_REAP_MAX + 120]};
			};
		};
	} forEach VIOC_FB_OFF;
	VIOC_FB_OFF = VIOC_FB_OFF - [-1];
};

VIOC_FB_fnc_serverLoop = {
	waitUntil {sleep 2; !isNil "CTI_InitTowns" && {!isNil "CTI_Init_Server"}};
	waitUntil {sleep 2; ({isNil {_x getVariable "cti_town_sideID"}} count CTI_Towns) == 0};
	sleep 5;
	call VIOC_FB_fnc_classify;
	while {!(missionNamespace getVariable ["CTI_GameOver", false])} do {
		call VIOC_FB_fnc_tick;
		sleep VIOC_FB_PERIOD;
	};
};

