while { time <= _req_time_out && alive _factory && {isNil "VIOC_FB_fnc_waitOk" || {[_factory] call VIOC_FB_fnc_waitOk}} } do { sleep .25 }; //--- VIOC forward_bases: la espera se corta si la base avanzada se pierde

